public class SearchController : SurfaceController
{
    private readonly IImobisoftSearchService _search;

    public async Task<IActionResult> Results(string q, int page = 1)
    {
        SearchResponse results = await _search.SearchAsync(q, page: page);
        return View(results);
    }
}

@foreach (var filter in Context.GetSearchFilters())
{
    foreach (var choice in filter.Values)
    {
        <a href="@Context.ToggleFilterUrl(filter.Alias, choice.Value)">@choice.Label (@choice.Count)</a>
    }
}
